import { setThemePreferences } from "../helpers/theme-preferences";
import { expectAutomaticPremiumShine } from "../helpers/premium-shine";
import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";

const themes = [
  ["lavender", "purple", "light", "rgb(255, 255, 255)"],
  ["nightbloom", "purple", "dark", "rgb(255, 255, 255)"],
  ["chalk", "vercel", "light", "rgb(255, 255, 255)"],
  ["obsidian", "vercel", "dark", "rgb(10, 10, 10)"],
] as const;

test("primary gradients and Upgrade shine work across themes and widths", async ({
  page,
  browser,
}, testInfo) => {
  test.skip(testInfo.project.name !== "desktop", "Own viewport matrix");
  test.setTimeout(240_000);
  const publicContext = await browser.newContext({ reducedMotion: "reduce" });
  const publicPage = await publicContext.newPage();
  await page.route("**/api/billing/status", async (route) => {
    const response = await route.fetch();
    await route.fulfill({
      response,
      json: {
        ...(await response.json()),
        configured: true,
        checkoutEnabled: true,
        plan: "FREE",
        status: "NONE",
        isSuspended: false,
        checkoutState: null,
      },
    });
  });
  for (const [name, appearance, mode, ink] of themes) {
    await setThemePreferences(page, appearance, mode);
    await setThemePreferences(publicPage, appearance, mode);
    for (const width of [1920, 1366, 390]) {
      await page.setViewportSize({ width, height: 1000 });
      await page.goto("/usage?country=US");
      const card = page.getByRole("region", { name: "Free", exact: true });
      const button = card.getByRole("button", {
        name: "Upgrade to Premium",
        exact: true,
      });
      await expect(button).toBeEnabled();
      await expect(button).toHaveClass(/upgrade-shine/);
      await expect(button).toHaveCSS("color", ink);
      expect(
        await button.evaluate((el) => getComputedStyle(el).backgroundImage),
      ).toContain("linear-gradient(95deg");
      const price = card.locator("[data-localized-price] b");
      await expect(price).toHaveCSS("background-clip", "text");
      expect(
        await price.evaluate((el) => getComputedStyle(el).backgroundImage),
      ).toContain("linear-gradient");
      await button.focus();
      expect(
        await button.evaluate((el) => getComputedStyle(el).outlineStyle),
      ).toBe("solid");
      await page.emulateMedia({ reducedMotion: "no-preference" });
      await page.mouse.move(0, 0);
      await expectAutomaticPremiumShine(button);
      await button.evaluate((el) => el.setAttribute("aria-busy", "true"));
      expect(
        await button.evaluate((el) => getComputedStyle(el, "::before").display),
      ).toBe("none");
      await button.evaluate((el) => {
        el.removeAttribute("aria-busy");
        el.setAttribute("disabled", "");
      });
      expect(
        await button.evaluate((el) => getComputedStyle(el, "::before").display),
      ).toBe("none");
      await button.evaluate((el) => {
        el.removeAttribute("disabled");
        el.setAttribute("aria-disabled", "true");
      });
      expect(
        await button.evaluate((el) => getComputedStyle(el, "::before").display),
      ).toBe("none");
      await button.evaluate((el) => el.removeAttribute("aria-disabled"));
      await page.emulateMedia({ reducedMotion: "reduce" });
      expect(
        await button.evaluate((el) => getComputedStyle(el, "::before").display),
      ).toBe("none");
      await card.screenshot({
        path: testInfo.outputPath(`${name}-${width}.png`),
      });
      await publicPage.setViewportSize({ width, height: 1000 });
      await publicPage.goto("/pricing?country=US");
      // Anonymous pages gate Premium themes. Exercise their CSS without changing entitlements.
      await publicPage
        .getByRole("button", { name: "Choose appearance" })
        .click();
      await publicPage.keyboard.press("Escape");
      await publicPage.locator("html").evaluate(
        (root, { appearance, mode }) => {
          root.dataset.appearance = appearance;
          root.dataset.theme = mode;
        },
        { appearance, mode },
      );
      const upgrade = publicPage.getByRole("button", {
        name: "Upgrade to Premium",
        exact: true,
      });
      await expect(upgrade).toHaveClass(/upgrade-shine/);
      await publicPage.emulateMedia({ reducedMotion: "no-preference" });
      await expectAutomaticPremiumShine(upgrade);
      await publicPage.emulateMedia({ reducedMotion: "reduce" });
      await expect(upgrade).toHaveCSS("color", ink);
      expect(
        await upgrade.evaluate((el) => getComputedStyle(el).backgroundImage),
      ).toContain("linear-gradient(135deg");
    }
  }
  for (const [, appearance, mode, ink] of themes) {
    await setThemePreferences(publicPage, appearance, mode);
    await publicPage.goto("/?country=US");
    await publicPage
      .getByRole("button", {
        name:
          mode === "dark" ? "Switch to light theme" : "Switch to dark theme",
        exact: true,
      })
      .click();
    await publicPage.locator("html").evaluate(
      (root, { appearance, mode }) => {
        root.dataset.appearance = appearance;
        root.dataset.theme = mode;
      },
      { appearance, mode },
    );
    const upgrades = publicPage.getByRole("button", {
      name: "Upgrade to Premium",
      exact: false,
    });
    expect(await upgrades.count()).toBeGreaterThan(0);
    for (const upgrade of await upgrades.all()) {
      await expect(upgrade).toHaveClass(/upgrade-shine/);
      await expect(upgrade).toHaveCSS("color", ink);
      await publicPage.emulateMedia({ reducedMotion: "no-preference" });
      await expectAutomaticPremiumShine(upgrade);
      await publicPage.emulateMedia({ reducedMotion: "reduce" });
    }
  }
  await publicContext.close();
});

test("feature upgrade buttons shine while small premium links stay static", async ({
  page,
  themeUser,
}) => {
  await setThemeQuotaGating(true);
  await setThemePlan(themeUser, "FREE");
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/templates");
  const upgrade = page.getByRole("link", {
    name: "View Premium plan",
    exact: true,
  });
  await expectAutomaticPremiumShine(upgrade);
  await page.goto("/settings");
  const links = page.getByRole("link", {
    name: "View Premium plan",
    exact: true,
  });
  await expect(links.first()).toBeVisible();
  for (const link of await links.all()) {
    await expect(link).not.toHaveClass(/upgrade-shine/);
    expect(
      await link.evaluate(
        (el) => getComputedStyle(el, "::before").animationName,
      ),
    ).toBe("none");
  }
});
